import fs from "node:fs";
const D="<scratch>";
export const dana=JSON.parse(fs.readFileSync(D+"dana-token.json"));
export const shady=JSON.parse(fs.readFileSync(D+"shady-token.json"));
export const LOG=D+"reports/rin-log.txt";
export async function call(label,method,url,{token,body,headers,cookie}={}){
  const h={...(headers||{})}; if(body!==undefined)h["content-type"]="application/json";
  if(token)h.authorization="Bearer "+token; if(cookie)h.cookie=cookie;
  const t=Date.now();
  const r=await fetch("http://localhost:8810"+url,{method,headers:h,body:body!==undefined?(typeof body==="string"?body:JSON.stringify(body)):undefined,redirect:"manual"});
  const txt=await r.text(); const ms=Date.now()-t;
  const sh=(s)=>s.replace(/(done_|dpk_)[A-Za-z0-9_-]+/g,"$1***");
  const reqShow=body===undefined?"":(typeof body==="string"?body:JSON.stringify(body));
  const out=`### ${label}\n${method} ${url} ${reqShow.length>600?reqShow.slice(0,600)+"...[trunc]":reqShow}\n=> ${r.status} (${ms}ms) ${r.headers.get("location")||""}\n${sh(txt).slice(0,1800)}\n\n`;
  fs.appendFileSync(LOG,out);
  let j; try{j=JSON.parse(txt)}catch{}
  return {status:r.status,json:j,text:txt,headers:r.headers};
}
export const agent=(label,tool,args={})=>call(label,"POST","/api/agent/"+tool,{token:dana.token||dana.key||dana.agentToken,body:args});
